import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"遯","description":"周易正义 - 遯","frontmatter":{"title":"遯","description":"周易正义 - 遯"},"headers":[],"relativePath":"zh/classics/zhengyi/033.md","filePath":"zh/classics/zhengyi/033.md"}'),l={name:"zh/classics/zhengyi/033.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天山遁</p></blockquote><blockquote><p>卦辞：亨，小利贞。</p></blockquote><blockquote><p>彖曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉！</p></blockquote><h1 id="遯" tabindex="-1">遯 <a class="header-anchor" href="#遯" aria-label="Permalink to “遯”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“遯”亨者，遯者，隐退逃避之名。阴长之卦，小人方用，君子日消。君子当此之时，若不隐遯避世，即受其害。须遯而后得通，故曰“遯亨”。“小利贞”者，阴道初始浸长，正道亦未全灭，故曰“小利贞”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="遯亨-遯而亨也。-​" tabindex="-1">“遯亨”，遯而亨也。 ​ <a class="header-anchor" href="#遯亨-遯而亨也。-​" aria-label="Permalink to ““遯亨”，遯而亨也。 ​”">​</a></h3><p>王弼：遯之为义，遯乃通也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“遯而亨”者，此释遯之所以得亨通之义。小人之道方长，君子非遯不通，故曰：“遯而亨也”。</p><h3 id="刚当位而应-与时行也。-​" tabindex="-1">刚当位而应，与时行也。 ​ <a class="header-anchor" href="#刚当位而应-与时行也。-​" aria-label="Permalink to “刚当位而应，与时行也。 ​”">​</a></h3><p>王弼：谓五也。“刚当位而应”，非否亢也。遯不否亢，能“与时行也”。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：举九五之爻，释所以能遯而致亨之由，良由九五以刚而当其位，有应於二，非为否亢。遯不否亢，即是相时而动，所以遯而得亨，故云“刚当位而应，与时行也”。</p><h3 id="小利贞-浸而长也。-​" tabindex="-1">“小利贞”，浸而长也。 ​ <a class="header-anchor" href="#小利贞-浸而长也。-​" aria-label="Permalink to ““小利贞”，浸而长也。 ​”">​</a></h3><p>王弼：阴道欲浸而长，正道亦未全灭，故“小利贞”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“小利贞”之义。浸者渐进之名。若阴德暴进，即消正道。良由二阴渐长而正道亦未即全灭，故云“小利贞”也。</p><h3 id="遯之时义大矣哉-​" tabindex="-1">遯之时义大矣哉！ ​ <a class="header-anchor" href="#遯之时义大矣哉-​" aria-label="Permalink to “遯之时义大矣哉！ ​”">​</a></h3><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：叹美遯德。相时度宜，避世而遯，自非大人照几不能如此，其义甚大，故云“大矣哉”。</p><h3 id="《象》曰-天下有山-遯。-​" tabindex="-1">《象》曰：天下有山，遯。 ​ <a class="header-anchor" href="#《象》曰-天下有山-遯。-​" aria-label="Permalink to “《象》曰：天下有山，遯。 ​”">​</a></h3><p>王弼：天下有山，阴长之象。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰：天下有山，遯”。○正义曰：“天下有山，遯”者，山者阴类，进在天下，即是山势欲上逼於天，天性高远，不受於逼，是遯避之象，故曰“天下有山，遯”。○注“天下有山”至“之象”。○正义曰：积阳为天，积阴为地。山者，地之高峻，今上逼於天，是阴长之象。</p><h3 id="君子以远小人-不恶而严。-​" tabindex="-1">君子以远小人，不恶而严。 ​ <a class="header-anchor" href="#君子以远小人-不恶而严。-​" aria-label="Permalink to “君子以远小人，不恶而严。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：君子当此遯避之时，小人进长，理须远避，力不能讨，故不可为恶，复不可与之亵渎，故曰“不恶而严”。</p><h2 id="初六-遯尾-厉-勿用有攸往。-​" tabindex="-1">初六：遯尾，厉，勿用有攸往。 ​ <a class="header-anchor" href="#初六-遯尾-厉-勿用有攸往。-​" aria-label="Permalink to “初六：遯尾，厉，勿用有攸往。 ​”">​</a></h2><p>王弼：“遯”之为义，辟内而之外者也。“尾”之为物，最在体后者也。处遯之时，不往何灾，而为“遯尾”，祸所及也。危至而后行，难可免乎？厉则“勿用有攸往”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“遯尾厉”者，为遯之尾，最在后遯者也。小人长於内，应出外以避之，而最在卦内，是遯之为后也。逃遯之世，宜速远而居先，而为“遯尾”，祸所及也，故曰“遯尾厉”也。“勿用有攸往”者，危厉既至，则当“固穷”，“危行言逊”，勿用更有所往，故曰“勿用有攸往”。</p><h3 id="《象》曰-遯尾-之厉-不往何灾也。-​" tabindex="-1">《象》曰：“遯尾”之厉，不往何灾也。 ​ <a class="header-anchor" href="#《象》曰-遯尾-之厉-不往何灾也。-​" aria-label="Permalink to “《象》曰：“遯尾”之厉，不往何灾也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“不往何灾”者，《象》释当遯之时，宜须出避。而“勿用有攸往”者，既为“遯尾”，出必见执，不如不往，不往即无灾害。“何灾”者，犹言无灾也。与何伤、何咎之义同也。</p><h2 id="六二-执之用黄牛之革-莫之胜说。-​" tabindex="-1">六二：执之用黄牛之革，莫之胜说。 ​ <a class="header-anchor" href="#六二-执之用黄牛之革-莫之胜说。-​" aria-label="Permalink to “六二：执之用黄牛之革，莫之胜说。 ​”">​</a></h2><p>王弼：居内处中，为遯之主，物皆遯巳，何以固之？若能执乎理中厚顺之道以固之也，则莫之胜解。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“执之用黄牛之革莫之胜说”者，逃遯之世，避内出外，二既处中居内，即非遯之人也。既非遯之人，便为所遯之主，物皆弃巳而遯，何以执固留之？惟有中和厚顺之道可以固而安之也。能用此道，则不能胜巳解脱而去也。黄中之色，以譬中和。牛性顺从，皮体坚厚，牛革以譬厚顺也。六三居中得位，亦是能用中和厚顺之道，故曰“执之用黄牛之革莫之胜说”也。</p><h3 id="《象》曰-执用黄牛-固志也。-​" tabindex="-1">《象》曰：执用黄牛，固志也。 ​ <a class="header-anchor" href="#《象》曰-执用黄牛-固志也。-​" aria-label="Permalink to “《象》曰：执用黄牛，固志也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“固志”者，坚固遯者之志，使不去已也。</p><h2 id="九三-系遯-有疾厉-畜臣妾-吉。-​" tabindex="-1">九三：系遯，有疾厉，畜臣妾，吉。 ​ <a class="header-anchor" href="#九三-系遯-有疾厉-畜臣妾-吉。-​" aria-label="Permalink to “九三：系遯，有疾厉，畜臣妾，吉。 ​”">​</a></h2><p>王弼：在内近二，以阳附阴，宜遯而系，故曰“系遯”。“遯”之为义，宜远小人，以阳附阴，系於所在，不能远害，亦巳惫矣，宜其屈辱而危厉也。系於所在，“畜臣妾”可也。施於大事，凶之道也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“系遯”者，九三无应於上，与二相比，以阳附阴，系意在二，处遯之世，而意有所系，故曰“系遯”。“有疾厉”者，“遯”之为义，宜远小人。既系於阴，即是“有疾惫”而致危厉，故曰“有疾厉”也。“畜臣妾吉”者，亲於所近，系在於下，施之於人，畜养臣妾则可矣，大事则凶，故曰：“畜臣妾吉。”</p><h3 id="《象》曰-系遯-之厉-有疾惫也。-畜臣妾-吉-不可大事也。-​" tabindex="-1">《象》曰：“系遯”之厉，有疾惫也。“畜臣妾，吉”，不可大事也。 ​ <a class="header-anchor" href="#《象》曰-系遯-之厉-有疾惫也。-畜臣妾-吉-不可大事也。-​" aria-label="Permalink to “《象》曰：“系遯”之厉，有疾惫也。“畜臣妾，吉”，不可大事也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“不可大事”者，释此“系遯”之人，以“畜臣妾吉”，明其不可为大事也。</p><h2 id="九四-好遯-君子吉-小人否。-​" tabindex="-1">九四：好遯，君子吉，小人否。 ​ <a class="header-anchor" href="#九四-好遯-君子吉-小人否。-​" aria-label="Permalink to “九四：好遯，君子吉，小人否。 ​”">​</a></h2><p>王弼：处於外而有应於内，君子“好遯”，故能舍之，小人系恋，是以“否”也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九四处在於外，而有应於内。处外即意欲远遯，应内则未能弃舍。若好遯君子，超然不顾，所以得吉。小人有所系恋，即不能遯，故曰“小人否”也。</p><h3 id="《象》曰-君子-好遯-小人否-也。-​" tabindex="-1">《象》曰：君子“好遯”，“小人否”也。 ​ <a class="header-anchor" href="#《象》曰-君子-好遯-小人否-也。-​" aria-label="Permalink to “《象》曰：君子“好遯”，“小人否”也。 ​”">​</a></h3><p>王弼：音臧否之否。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：嫌读为“圯”，故音之也。</p><h2 id="九五-嘉遯-贞吉。-​" tabindex="-1">九五：嘉遯，贞吉。 ​ <a class="header-anchor" href="#九五-嘉遯-贞吉。-​" aria-label="Permalink to “九五：嘉遯，贞吉。 ​”">​</a></h2><p>王弼：遯而得正，反制於内。小人应命，率正其志，“不恶而严”，得正之吉，遯之嘉也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“嘉遯贞吉”者，嘉，美也。五居於外，得位居中，是“遯而得正”。二为已应，不敢违拒，从五之命，率正其志，“遯而得正，反制於内”，“不恶而严，得正之吉”，为遯之美，故曰“嘉遯贞吉”也。</p><h3 id="《象》曰-嘉遯-贞吉-以正志也。-​" tabindex="-1">《象》曰：“嘉遯，贞吉”，以正志也。 ​ <a class="header-anchor" href="#《象》曰-嘉遯-贞吉-以正志也。-​" aria-label="Permalink to “《象》曰：“嘉遯，贞吉”，以正志也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“以正志”者，小人应命，不敢为邪，是五能正二之志，故成遯之美也。</p><h2 id="上九-肥遯-无不利。-​" tabindex="-1">上九：肥遯，无不利。 ​ <a class="header-anchor" href="#上九-肥遯-无不利。-​" aria-label="Permalink to “上九：肥遯，无不利。 ​”">​</a></h2><p>王弼：最处外极，无应於内，超然绝志，心无疑顾，忧患不能累，矰缴不能及，是以“肥遯无不利”也。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>“上九，肥遯无不利”。○正义曰：《子夏传》曰：“肥，饶裕也。”四、五虽在於外，皆在内有应，犹有反顾之心。惟上九最在外极，无应於内，心无疑顾，是遯之最优，故曰“肥遯”。遯而得肥，无所不利，故云“无不利”也。注“最处外极”至“无不利也”。○正义曰：矰，矢名也。郑注《周礼》“”结缴於矢谓之矰。”缴，《字林》及《说文》云：“缴，生丝缕也。”</p><h3 id="《象》曰-肥遯-无不利-无所疑也。-​" tabindex="-1">《象》曰：“肥遯，无不利”，无所疑也。 ​ <a class="header-anchor" href="#《象》曰-肥遯-无不利-无所疑也。-​" aria-label="Permalink to “《象》曰：“肥遯，无不利”，无所疑也。 ​”">​</a></h3>',70)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
